def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Each top-row marker is an apex; the two diagonals spreading downward
    # form the sides of a triangular region. Fill strictly between them.
    for apex, color in enumerate(grid[0]):
        if color == 0:
            continue
        for r in range(1, h):
            left, right = apex-r, apex+r
            for c in range(max(0, left+1), min(w, right)):
                if out[r][c] == 0:
                    out[r][c] = 2
    return out
